mapper.select:
select count(*)::integer as recent_practice_count, count(*) filter (where ie.reaction_type = 'cooperating')::integer as cooperating_count, count(*) filter (where ie.reaction_type = 'hesitant')::integer as hesitant_count, count(*) filter (where ie.reaction_type = 'resisting')::integer as resisting_count, count(*) filter (where ie.reaction_type = 'no_response')::integer as no_response_count, count(*) filter (where ie.reaction_type = 'other')::integer as other_count from interaction_events ie
join household_members hm on hm.account_id = ie.account_id join households h on h.household_id = hm.household_id where hm.household_id = #{householdId} and hm.status = 'active' and h.status = 'active'
where ie.account_id = #{ownerAccountId}
and ie.client_timestamp >= #{weekStart,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler} and ie.client_timestamp <= #{now,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
